// ── Helpers ─────────────────────────────────────────────────────────────────
function getMondayOfWeek(offset) {
  const today = new Date();
  const diff  = today.getDay() === 0 ? -6 : 1 - today.getDay();
  const mon   = new Date(today);
  mon.setDate(today.getDate() + diff + (offset || 0) * 7);
  mon.setHours(0, 0, 0, 0);
  return mon;
}

function formatWeekRange(monday) {
  const fri = new Date(monday);
  fri.setDate(monday.getDate() + 4);
  return `${MONTHS[monday.getMonth()]} ${monday.getDate()} – ${MONTHS[fri.getMonth()]} ${fri.getDate()}`;
}

function timeToMinutes(timeStr) {
  if (!timeStr) return 600;
  const m = timeStr.match(/(\d+):(\d+)\s*(AM|PM)/i);
  if (!m) return 600;
  let h = parseInt(m[1]);
  const min = parseInt(m[2]);
  const ap = m[3].toUpperCase();
  if (ap === 'PM' && h !== 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return h * 60 + min;
}

// "14:30" → "2:30 PM"
function to12h(val) {
  if (!val) return '';
  const parts = val.split(':');
  const h = parseInt(parts[0]);
  const m = parts[1] || '00';
  const ap = h >= 12 ? 'PM' : 'AM';
  const hr = h % 12 === 0 ? 12 : h % 12;
  return `${hr}:${m} ${ap}`;
}

// "10:30 AM" → "10:30"
function to24h(display) {
  if (!display) return '09:00';
  const m = display.match(/(\d+):(\d+)\s*(AM|PM)/i);
  if (!m) return '09:00';
  let h = parseInt(m[1]);
  const ap = m[3].toUpperCase();
  if (ap === 'PM' && h !== 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return `${String(h).padStart(2, '0')}:${m[2]}`;
}

function fmtValue(v) {
  if (!v || isNaN(v)) return '₹0';
  if (v / 100000 >= 1) return '₹' + (v / 100000).toFixed(1) + 'L';
  if (v / 1000 >= 1)   return '₹' + (v / 1000).toFixed(1) + 'K';
  return '₹' + v;
}

// ── Component ─────────────────────────────────────────────────────────────────
class MyVisitPlan extends Component {
  constructor(props) {
    super(props);
    const q = new URLSearchParams(window.location.search);
    this.state = {
      userId:  q.get('userid') || 'gsrao@jeftechno.com', // TODO: remove test fallback; rely on ?userid=<email> in production
      loginid: q.get('checkin_id'),
      env:     q.get('env'),

      weekOffset:      0,
      planStatus:      'Draft',
      activeDay:       'Mon',
      searchText:      '',

      systemSuggested: [],
      otherClients:    [],
      queueLoading:    true,
      queueError:      '',

      scheduled:       { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [] },
      slotCounter:     1,
      lastSaved:       null,
      planSaving:      false,

      // schedule dialog
      dropDialogOpen:        false,
      dropPendingOffer:      null,
      dropPendingDay:        null,
      dropPendingFromDay:    null,
      dropPendingFromSlotId: null,
      dropTime:              '10:00',
      dropDuration:          60,
      dropReminder:          15,
      dropVisitType:         'In-person',
      dropConflict:          '',

      // client detail sheet
      detailClient: null,

      // add-visit dialog (single dialog: name, day, type, time, duration, reminder)
      addOpen:      false,
      addName:      '',
      addDay:       'Mon',
      addType:      'In-person',
      addTime:      '10:00',
      addDuration:  60,
      addReminder:  15,
      addConflict:  '',
      addSaving:    false,

      // add-client dialog (ported from CheckIn → tbl_temp_client_details)
      acOpen:            false,
      acName:            '',
      acPhone:           '',
      acContactPerson:   '',
      acCity:            '',
      acState:           '',
      acRegion:          '',
      acRegionsData:     [],
      acRegionsLoading:  false,
      acSaving:          false,

      // attendance / logout
      marking:    false,
      LogoutFlag: false,

      // visit selection (for "check in to this visit")
      selectedSlotId: null,
      selectedDay:    null,

      // snackbar
      SnackBar: false, SnackBarVariant: 'warning', snackBarMessage: '', SnackbarTimeOut: 5000,
    };
  }

  async componentDidMount() {
    // Default the active day to today if it's a weekday, else Monday.
    const dow = new Date().getDay(); // 0 Sun .. 6 Sat
    if (dow >= 1 && dow <= 5) this.setState({ activeDay: DAYS[dow - 1] });
    await this.loadClientQueue();
    await this.loadPlan(this.getWeekStart());
  }

  Snackbar = (variant, message, timeout) => {
    this.setState({ SnackBar: true, SnackBarVariant: variant, snackBarMessage: message, SnackbarTimeOut: timeout || 5000 });
  }

  // ── API ─────────────────────────────────────────────────────────────────────
  loadClientQueue = async () => {
    const email = this.state.userId;
    if (!email) { this.setState({ queueLoading: false, queueError: 'User not found. Please open from the app.' }); return; }
    try {
      this.setState({ queueLoading: true, queueError: '' });
      const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/getClientQueue', method: 'POST', data: { email } });
      if (resp && resp.respCode === 1) {
        this.setState({ systemSuggested: resp.systemSuggested || [], otherClients: resp.otherClients || [], queueLoading: false });
      } else {
        this.setState({ queueLoading: false, queueError: (resp && resp.respText) || 'Failed to load client queue.' });
      }
    } catch (err) {
      this.setState({ queueLoading: false, queueError: err.message });
    }
  }

  getWeekStart() {
    const d = getMondayOfWeek(this.state.weekOffset);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  }

  loadPlan = async (weekStart) => {
    const email = this.state.userId;
    if (!email) return;
    try {
      const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/getPlan', method: 'POST', data: { email, weekStart } });
      if (resp && resp.respCode === 1 && resp.plan) {
        const sched = resp.plan.scheduled || { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [] };
        let maxId = 0;
        DAYS.forEach((d) => (sched[d] || []).forEach((s) => {
          const n = parseInt((s.slotId || '').replace('s_', ''));
          if (!isNaN(n) && n > maxId) maxId = n;
        }));
        this.setState({ scheduled: sched, planStatus: resp.plan.planStatus || 'Draft', slotCounter: maxId + 1 });
      } else {
        this.setState({ scheduled: { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [] }, planStatus: 'Draft' });
      }
    } catch (err) {
      this.setState({ scheduled: { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [] }, planStatus: 'Draft' });
    }
  }

  callSavePlan = async (status) => {
    if (this.state.planSaving) return;
    const email = this.state.userId;
    const weekStart = this.getWeekStart();
    this.setState({ planSaving: true });
    try {
      const resp = await ProcessRequest({
        urlapi: 'salesvisit_stage/savePlan', method: 'POST',
        data: { email, weekStart, scheduled: this.state.scheduled, planStatus: status },
      });
      if (resp && resp.respCode === 1) {
        this.setState({ planSaving: false, lastSaved: new Date(), planStatus: status });
        this.Snackbar('success', status === 'Submitted' ? 'Plan submitted to RM.' : 'Draft saved.', 4000);
      } else {
        this.setState({ planSaving: false });
        this.Snackbar('warning', (resp && resp.respText) || 'Could not save plan.', 5000);
      }
    } catch (err) {
      this.setState({ planSaving: false });
      this.Snackbar('warning', err.message, 5000);
    }
  }

  saveDraft  = () => this.callSavePlan('Draft');
  submitToRM = () => this.callSavePlan('Submitted');

  // ── Week nav ─────────────────────────────────────────────────────────────────
  prevWeek = () => {
    if (this.state.weekOffset <= 0) return;
    this.setState((s) => ({ weekOffset: s.weekOffset - 1 }), () => this.loadPlan(this.getWeekStart()));
  }
  nextWeek = () => {
    if (this.state.weekOffset >= MAX_WEEK_OFFSET) return;
    this.setState((s) => ({ weekOffset: s.weekOffset + 1 }), () => this.loadPlan(this.getWeekStart()));
  }

  getWeekDates() {
    const mon = getMondayOfWeek(this.state.weekOffset);
    return DAYS.map((day, i) => {
      const d = new Date(mon);
      d.setDate(mon.getDate() + i);
      return { day, date: d.getDate(), month: MONTHS[d.getMonth()] };
    });
  }

  // ── Derived priority (matches web) ──────────────────────────────────────────
  clientPriority(client) {
    const offers = client.offers || [];
    if (client.hasOverdueDebtors)                  return 'high';
    if (offers.some((o) => o.priority === 'high')) return 'high';
    if (client.totalDebtorAmount > 0)              return 'medium';
    if (offers.some((o) => o.priority === 'medium')) return 'medium';
    return 'low';
  }

  // clientIds already placed anywhere in the week
  scheduledClientIds() {
    const ids = new Set();
    DAYS.forEach((d) => (this.state.scheduled[d] || []).forEach((s) => ids.add(s.clientId)));
    return ids;
  }

  // Unscheduled queue clients (priority-sorted), filtered by search
  unscheduledClients() {
    const placed = this.scheduledClientIds();
    let list = this.state.systemSuggested.concat(this.state.otherClients).filter((c) => !placed.has(c.clientId));
    const q = this.state.searchText.trim().toLowerCase();
    if (q) {
      list = list.filter((c) =>
        (c.clientName || '').toLowerCase().includes(q) ||
        (c.offers || []).some((o) => (o.name || '').toLowerCase().includes(q)));
    }
    const rank = { high: 3, medium: 2, low: 1 };
    return list.slice().sort((a, b) => {
      const pr = (rank[this.clientPriority(b)] || 0) - (rank[this.clientPriority(a)] || 0);
      if (pr !== 0) return pr;
      return (b.maxExposure || 0) - (a.maxExposure || 0);
    });
  }

  getStats() {
    const { scheduled } = this.state;
    let total = 0, visits = 0, calls = 0;
    DAYS.forEach((d) => (scheduled[d] || []).forEach((s) => {
      total++;
      if (s.type === 'In-person') visits++; else calls++;
    }));
    return { total, visits, calls, unscheduled: this.unscheduledClients().length };
  }

  // ── Scheduling ───────────────────────────────────────────────────────────────
  offerFromClient(client) {
    return {
      clientId: client.clientId, name: client.clientName, client: client.clientName,
      type: client.type || 'In-person', value: client.totalValueFormatted,
      priority: this.clientPriority(client), sysRank: client.sysRank,
      note: client.note, offers: client.offers, debtors: client.debtors,
      totalValueFormatted: client.totalValueFormatted, totalDebtorAmountFormatted: client.totalDebtorAmountFormatted,
    };
  }

  openScheduleForClient = (client) => {
    const offer = this.offerFromClient(client);
    this.setState({
      dropDialogOpen: true, dropPendingOffer: offer, dropPendingDay: this.state.activeDay,
      dropPendingFromDay: null, dropPendingFromSlotId: null,
      dropTime: '10:00', dropDuration: 60, dropReminder: 15,
      dropVisitType: offer.type || 'In-person', dropConflict: '',
    });
  }

  openEditDialog = (slot, day) => {
    this.setState({
      dropDialogOpen: true, dropPendingOffer: slot, dropPendingDay: day,
      dropPendingFromDay: day, dropPendingFromSlotId: slot.slotId,
      dropTime: to24h(slot.time), dropDuration: slot.duration || 60,
      dropReminder: slot.reminder !== undefined ? slot.reminder : 15,
      dropVisitType: slot.type || 'In-person', dropConflict: '',
    });
  }

  cancelDrop = () => this.setState({ dropDialogOpen: false, dropPendingOffer: null, dropPendingDay: null, dropPendingFromDay: null, dropPendingFromSlotId: null });

  confirmDrop = async () => {
    const {
      dropPendingOffer, dropPendingDay, dropPendingFromDay, dropPendingFromSlotId,
      dropTime, dropDuration, dropReminder, dropVisitType, scheduled, slotCounter,
    } = this.state;

    // In-person overlap check on the target day
    if (dropVisitType === 'In-person') {
      const newStart = timeToMinutes(to12h(dropTime));
      const newEnd   = newStart + dropDuration;
      const conflict = (scheduled[dropPendingDay] || []).find((s) => {
        if (s.type !== 'In-person') return false;
        if (s.slotId === dropPendingFromSlotId) return false;
        const sStart = timeToMinutes(s.time);
        const sEnd   = sStart + (s.duration || 60);
        return newStart < sEnd && newEnd > sStart;
      });
      if (conflict) {
        this.setState({ dropConflict: `"${conflict.name}" is already In-person at ${conflict.time} (${conflict.duration || 60} min). Choose a different time.` });
        return;
      }
    }

    const next = {};
    DAYS.forEach((d) => { next[d] = (scheduled[d] || []).slice(); });
    if (dropPendingFromDay && dropPendingFromSlotId) {
      next[dropPendingFromDay] = next[dropPendingFromDay].filter((s) => s.slotId !== dropPendingFromSlotId);
    }
    const slot = {
      ...dropPendingOffer,
      slotId: `s_${slotCounter}`, time: to12h(dropTime),
      duration: dropDuration, reminder: dropReminder, type: dropVisitType,
    };
    const daySlots = next[dropPendingDay].slice();
    daySlots.push(slot);
    daySlots.sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
    next[dropPendingDay] = daySlots;

    await new Promise((resolve) => this.setState({
      scheduled: next, dropDialogOpen: false, dropPendingOffer: null, dropPendingDay: null,
      dropPendingFromDay: null, dropPendingFromSlotId: null, dropConflict: '', slotCounter: slotCounter + 1,
    }, resolve));
    // Persist the edit/move/schedule so the plan is updated immediately.
    await this.callSavePlan(this.state.planStatus === 'Submitted' ? 'Submitted' : 'Draft');
  }

  removeSlot = async (day, slotId) => {
    const next = { ...this.state.scheduled };
    next[day] = next[day].filter((s) => s.slotId !== slotId);
    await new Promise((resolve) => this.setState({ scheduled: next }, resolve));
    await this.callSavePlan(this.state.planStatus === 'Submitted' ? 'Submitted' : 'Draft');
  }

  // ── Select a visit → check in ────────────────────────────────────────────────
  toggleSelectSlot = (day, slot) => {
    if (this.state.selectedSlotId === slot.slotId) {
      this.setState({ selectedSlotId: null, selectedDay: null });
    } else {
      this.setState({ selectedSlotId: slot.slotId, selectedDay: day });
    }
  }

  selectedSlot = () => {
    const { selectedSlotId, selectedDay, scheduled } = this.state;
    if (!selectedSlotId || !selectedDay) return null;
    return (scheduled[selectedDay] || []).find((s) => s.slotId === selectedSlotId) || null;
  }

  goToCheckin = () => {
    const slot = this.selectedSlot();
    if (!slot) return;
    const params = new URLSearchParams();
    params.set('client', slot.name || slot.client || '');
    if (slot.clientId) params.set('clientId', slot.clientId);
    params.set('locked', '1');
    // A "Call" visit skips the check-in form: check-in auto-submits, then forwards to checkout.
    if (slot.type !== 'In-person') {
      params.set('auto', '1');
      params.set('visit', 'Call');
    }
    if (this.state.userId) params.set('userid', this.state.userId);
    if (this.state.loginid) params.set('checkin_id', this.state.loginid);
    if (this.state.env) params.set('env', this.state.env);
    window.location.href = '/salesvisit_stage?' + params.toString();
  }

  // ── Add Visit (single dialog: name, day, type, time, duration, reminder) ──────
  openAdd  = () => this.setState({
    addOpen: true, addName: '', addDay: this.state.activeDay, addType: 'In-person',
    addTime: '10:00', addDuration: 60, addReminder: 15, addConflict: '', addSaving: false,
  });
  cancelAdd = () => this.setState({ addOpen: false });

  confirmAdd = async () => {
    const { addName, addDay, addType, addTime, addDuration, addReminder, scheduled, slotCounter } = this.state;
    const name = addName.trim();
    if (!name) { this.Snackbar('warning', 'Please enter a client name.', 4000); return; }

    // In-person overlap check on the chosen day
    if (addType === 'In-person') {
      const newStart = timeToMinutes(to12h(addTime));
      const newEnd   = newStart + addDuration;
      const conflict = (scheduled[addDay] || []).find((s) => {
        if (s.type !== 'In-person') return false;
        const sStart = timeToMinutes(s.time);
        return newStart < (sStart + (s.duration || 60)) && newEnd > sStart;
      });
      if (conflict) {
        this.setState({ addConflict: `"${conflict.name}" is already In-person at ${conflict.time} (${conflict.duration || 60} min). Choose a different time.` });
        return;
      }
    }

    const slot = {
      clientId: `custom_${slotCounter}`, name, client: name, offers: [], debtors: [],
      slotId: `s_${slotCounter}`, time: to12h(addTime),
      duration: addDuration, reminder: addReminder, type: addType, priority: 'low', value: '',
    };
    const next = {};
    DAYS.forEach((d) => { next[d] = (scheduled[d] || []).slice(); });
    next[addDay] = next[addDay].concat(slot).sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));

    // Add to the plan, then persist so the selected day's plan is updated.
    await new Promise((resolve) => this.setState({
      scheduled: next, slotCounter: slotCounter + 1, addOpen: false, addConflict: '',
    }, resolve));
    await this.callSavePlan(this.state.planStatus === 'Submitted' ? 'Submitted' : 'Draft');
  }

  // ── Add Client (ported from CheckIn → tbl_temp_client_details) ────────────────
  openAddClient = () => {
    this.setState({
      acOpen: true, acName: '', acPhone: '', acContactPerson: '',
      acCity: '', acState: '', acRegion: '', acSaving: false,
    });
    this.fetchAcRegions();
  }
  cancelAddClient = () => this.setState({ acOpen: false });

  fetchAcRegions = async () => {
    if (this.state.acRegionsData.length > 0) return;
    this.setState({ acRegionsLoading: true });
    const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/getRegions', method: 'POST', data: { userid: this.state.userId } });
    if (resp && resp.respCode === 1) this.setState({ acRegionsData: Array.isArray(resp.regions) ? resp.regions : [] });
    else this.Snackbar('warning', (resp && resp.respText) || 'Unable to load regions.', 5000);
    this.setState({ acRegionsLoading: false });
  }

  saveNewClient = async () => {
    const name    = this.state.acName.trim();
    const phone   = this.state.acPhone.trim();
    const contact = this.state.acContactPerson.trim();
    const city    = this.state.acCity.trim();
    const stateNm = this.state.acState.trim();
    const region  = this.state.acRegion;
    if (!name)                { this.Snackbar('warning', 'Please enter Client Name.', 4000); return; }
    if (!/^\d{10}$/.test(phone)) { this.Snackbar('warning', 'Please enter a valid 10-digit Phone Number.', 4000); return; }
    if (!contact)             { this.Snackbar('warning', 'Please enter Contact Person Name.', 4000); return; }
    if (!city)                { this.Snackbar('warning', 'Please enter City.', 4000); return; }
    if (!stateNm)             { this.Snackbar('warning', 'Please enter State.', 4000); return; }
    if (!region)              { this.Snackbar('warning', 'Please select Region.', 4000); return; }

    this.setState({ acSaving: true });
    const resp = await ProcessRequest({
      urlapi: 'salesvisit_stage/saveTempClientDetails', method: 'POST',
      data: {
        client_name: name, phone_number: phone, contact_person: contact,
        city: city, state: stateNm, region: region,
        loginid: this.state.loginid, userid: this.state.userId,
      },
    });
    if (resp && resp.respCode === 1 && resp.respText === 'success') {
      this.setState({ acOpen: false, acSaving: false });
      this.Snackbar('success', 'New client saved.', 4000);
    } else {
      this.setState({ acSaving: false });
      this.Snackbar('warning', resp ? resp.respText : 'Server not responding.', 5000);
    }
  }

  // ── Attendance / Logout (geo) ─────────────────────────────────────────────────
  withGeo(cb) {
    if (!navigator.geolocation) { cb('NA', 'NA'); return; }
    navigator.geolocation.getCurrentPosition(
      (p) => cb(p.coords.latitude, p.coords.longitude),
      () => cb('NA', 'NA')
    );
  }

  markAttendance = () => {
    if (this.state.marking) return;
    this.setState({ marking: true });
    this.withGeo(async (lat, long) => {
      try {
        const resp = await ProcessRequest({ urlapi: 'salesvisit_stage/markAttendance', method: 'POST', data: { username: this.state.userId, latitude: lat, longitude: long } });
        if (resp && resp.respCode === 1) this.Snackbar('success', 'Attendance marked.', 4000);
        else this.Snackbar('warning', (resp && resp.respText) || 'Could not mark attendance.', 5000);
      } catch (e) { this.Snackbar('warning', e.message, 5000); }
      this.setState({ marking: false });
    });
  }

  doLogout = () => {
    this.withGeo(async (lat, long) => {
      try {
        await ProcessRequest({ urlapi: 'salesvisit_stage/insertLogoutLog', method: 'POST', data: { username: this.state.userId, latitude: lat, longitude: long } });
      } catch (e) { /* ignore — still log the user out */ }
      this.setState({ LogoutFlag: true });
    });
  }

  goBack = () => { window.history.back(); }

  // ─── Render: top bar ────────────────────────────────────────────────────────
  renderTopBar() {
    const { planStatus, weekOffset } = this.state;
    const monday = getMondayOfWeek(weekOffset);
    const theme  = WEEK_THEME[weekOffset] || WEEK_THEME[0];
    const statusStyle =
      planStatus === 'Draft'     ? { bg: '#FFF8EE', color: C.med,   border: C.med   } :
      planStatus === 'Submitted' ? { bg: '#EEEAFF', color: C.brand, border: C.brand } :
                                   { bg: '#EAF3DE', color: C.low,   border: C.low   };
    return (
      <Paper elevation={2} sx={{ borderRadius: 0, flexShrink: 0, zIndex: 3 }}>
        <Box sx={{ px: 1.5, py: 1, display: 'flex', alignItems: 'center', gap: 0.5 }}>
          <IconButton size="small" onClick={this.goBack}><ArrowBack fontSize="small" /></IconButton>
          <Typography variant="subtitle1" fontWeight={700} sx={{ flex: 1, fontSize: 15 }}>My visit plan</Typography>
          <IconButton size="small" onClick={this.openAddClient} title="Add Client" sx={{ color: C.brand }}><PersonAdd fontSize="small" /></IconButton>
          <IconButton size="small" onClick={this.openAdd} title="Add Visit" sx={{ color: C.brand }}><AddLocationAlt fontSize="small" /></IconButton>
          <IconButton size="small" onClick={this.doLogout} title="Logout" sx={{ color: '#888' }}><LogoutIcon fontSize="small" /></IconButton>
        </Box>
        <Box sx={{ px: 1.5, pb: 1, display: 'flex', alignItems: 'center', gap: 1 }}>
          <IconButton size="small" onClick={this.prevWeek} disabled={weekOffset <= 0}><NavigateBefore fontSize="small" /></IconButton>
          <Box sx={{ flex: 1, textAlign: 'center' }}>
            <Typography sx={{ fontSize: 13, fontWeight: 600, color: '#333', lineHeight: 1.2 }}>{formatWeekRange(monday)}</Typography>
            <Typography sx={{ fontSize: 10, fontWeight: 700, color: theme.accent }}>{theme.label}</Typography>
          </Box>
          <IconButton size="small" onClick={this.nextWeek} disabled={weekOffset >= MAX_WEEK_OFFSET}><NavigateNext fontSize="small" /></IconButton>
          <Chip label={planStatus} size="small" sx={{ bgcolor: statusStyle.bg, color: statusStyle.color, border: `1px solid ${statusStyle.border}`, fontWeight: 700, fontSize: 11 }} />
        </Box>
      </Paper>
    );
  }

  // ─── Render: day strip ──────────────────────────────────────────────────────
  renderDayStrip() {
    const { activeDay, scheduled, weekOffset } = this.state;
    const theme = WEEK_THEME[weekOffset] || WEEK_THEME[0];
    const dates = this.getWeekDates();
    return (
      <Box sx={{ display: 'flex', gap: 0.8, px: 1.5, py: 1, overflowX: 'auto', flexShrink: 0, bgcolor: '#fafafa', borderBottom: '1px solid #eee' }}>
        {dates.map(({ day, date }) => {
          const count    = (scheduled[day] || []).length;
          const selected = activeDay === day;
          return (
            <Box key={day} onClick={() => this.setState({ activeDay: day })}
              sx={{
                minWidth: 60, flex: '0 0 auto', textAlign: 'center', py: 0.8, borderRadius: 2, cursor: 'pointer',
                border: `1.5px solid ${selected ? theme.accent : '#e0e0e0'}`,
                bgcolor: selected ? `${theme.accent}12` : 'white',
              }}>
              <Typography sx={{ fontSize: 10, fontWeight: 700, color: selected ? theme.accent : '#999', textTransform: 'uppercase' }}>{day}</Typography>
              <Typography sx={{ fontSize: 18, fontWeight: 800, lineHeight: 1.1, color: selected ? theme.accent : '#333' }}>{date}</Typography>
              <Typography sx={{ fontSize: 9, color: count ? C.brand : '#bbb', fontWeight: 600 }}>{count ? `${count} plan${count > 1 ? 's' : ''}` : '—'}</Typography>
            </Box>
          );
        })}
      </Box>
    );
  }

  // ─── Render: one scheduled card ─────────────────────────────────────────────
  renderScheduledCard(slot, day) {
    const ip = slot.type === 'In-person';
    const pClr = PRIORITY_COLOR[slot.priority] || C.low;
    const selected = this.state.selectedSlotId === slot.slotId;
    return (
      <React.Fragment key={slot.slotId}>
      <Paper elevation={0}
        onClick={() => this.toggleSelectSlot(day, slot)}
        sx={{ display: 'flex', mb: selected ? 0.5 : 0.8, borderRadius: 1.5, cursor: 'pointer', overflow: 'hidden',
          border: selected ? `2px solid ${C.brand}` : '1px solid #e8e8e8',
          bgcolor: selected ? `${C.brand}0D` : '#fff', '&:active': { bgcolor: '#f7f7f7' } }}>
        <Box sx={{ width: 4, flexShrink: 0, bgcolor: pClr }} />
        <Box sx={{ p: 1, flex: 1, minWidth: 0 }}>
          <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 0.5 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0 }}>
              {selected && <HowToReg sx={{ fontSize: 15, color: C.brand, flexShrink: 0 }} />}
              <Typography sx={{ fontSize: 12, fontWeight: 700, color: '#222', lineHeight: 1.3 }}>{slot.name}</Typography>
            </Box>
            <Box sx={{ display: 'flex', gap: 0.2, flexShrink: 0 }}>
              {(slot.offers && slot.offers.length > 0) || (slot.debtors && slot.debtors.length > 0) ? (
                <IconButton size="small" sx={{ p: '2px' }} onClick={(e) => { e.stopPropagation(); this.setState({ detailClient: slot }); }} title="Client detail"><Business sx={{ fontSize: 15, color: C.brand }} /></IconButton>
              ) : null}
              <IconButton size="small" sx={{ p: '2px' }} onClick={(e) => { e.stopPropagation(); this.openEditDialog(slot, day); }} title="Reschedule"><AccessTime sx={{ fontSize: 15, color: '#888' }} /></IconButton>
              <IconButton size="small" sx={{ p: '2px' }} onClick={(e) => { e.stopPropagation(); this.removeSlot(day, slot.slotId); }} title="Remove"><Close sx={{ fontSize: 15, color: '#999' }} /></IconButton>
            </Box>
          </Box>
          {slot.client && slot.client !== slot.name && (
            <Typography sx={{ fontSize: 10.5, color: '#888' }} noWrap>{slot.client}</Typography>
          )}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.8, mt: 0.5, flexWrap: 'wrap' }}>
            <Chip size="small"
              icon={ip ? <LocationOn sx={{ fontSize: '12px !important', color: `${C.sysBadgeText} !important` }} /> : <Phone sx={{ fontSize: '12px !important', color: '#1a5276 !important' }} />}
              label={`${slot.time} · ${slot.duration || 60}m · ${ip ? 'In-person' : 'Call'}`}
              sx={{ height: 20, fontSize: 10, fontWeight: 600, bgcolor: ip ? C.inPersonBg : C.callBg, color: ip ? C.sysBadgeText : '#1a5276', border: `1px solid ${ip ? C.inPersonBorder : C.callBorder}`, '& .MuiChip-label': { px: 0.7 } }} />
            {slot.value ? <Typography sx={{ fontSize: 10.5, fontWeight: 700, color: C.brand }}>{slot.value}</Typography> : null}
            {slot.reminder > 0 && (
              <Typography sx={{ fontSize: 9.5, color: '#aaa', display: 'flex', alignItems: 'center', gap: 0.2 }}>
                <NotificationsNone sx={{ fontSize: 11 }} />{slot.reminder}m
              </Typography>
            )}
          </Box>
        </Box>
      </Paper>
      {selected && (
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
          <Button variant="contained" size="small" onClick={this.goToCheckin} endIcon={<NavigateNext />}
            sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, fontSize: 12, fontWeight: 700, borderRadius: 1.5, px: 2 }}>
            Check in
          </Button>
        </Box>
      )}
      </React.Fragment>
    );
  }

  // ─── Render: day sections (all days) ────────────────────────────────────────
  renderDaySections() {
    const { scheduled, activeDay } = this.state;
    const dates = this.getWeekDates();
    return dates.map(({ day, date, month }) => {
      const slots = (scheduled[day] || []).slice().sort((a, b) => timeToMinutes(a.time) - timeToMinutes(b.time));
      const isActive = activeDay === day;
      return (
        <Box key={day} sx={{ mb: 1.5 }}>
          <Typography sx={{ fontSize: 11, fontWeight: 800, color: isActive ? C.brand : '#999', textTransform: 'uppercase', letterSpacing: 0.5, mb: 0.6 }}>
            {DAY_FULL[day]}, {month} {date}
          </Typography>
          {slots.length > 0
            ? slots.map((s) => this.renderScheduledCard(s, day))
            : (
              <Box onClick={() => this.setState({ activeDay: day })}
                sx={{ border: '1px dashed #d5d5d5', borderRadius: 1.5, py: 1.2, textAlign: 'center', cursor: 'pointer', color: '#bbb', fontSize: 11, bgcolor: isActive ? `${C.brand}08` : 'transparent' }}>
                + No visit planned — tap to add
              </Box>
            )}
        </Box>
      );
    });
  }

  // ─── Render: unscheduled offers ─────────────────────────────────────────────
  renderUnscheduled() {
    const list = this.unscheduledClients();
    const dates = this.getWeekDates();
    const active = dates.find((d) => d.day === this.state.activeDay);
    const activeLabel = active ? `${active.day}, ${active.month} ${active.date}` : this.state.activeDay;
    return (
      <Box sx={{ mt: 1 }}>
        <Divider sx={{ mb: 1 }} />
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.8 }}>
          <Typography sx={{ fontSize: 11, fontWeight: 800, color: '#666', textTransform: 'uppercase', letterSpacing: 0.4 }}>Unscheduled offers</Typography>
          <Typography sx={{ fontSize: 10, color: C.brand, fontWeight: 600 }}>tap to add to {activeLabel}</Typography>
        </Box>
        <TextField size="small" fullWidth placeholder="Search client or project…"
          value={this.state.searchText} onChange={(e) => this.setState({ searchText: e.target.value })}
          sx={{ mb: 1, '& .MuiInputBase-input': { fontSize: 12, py: '6px' }, '& .MuiOutlinedInput-root': { borderRadius: 1.5 } }} />
        {list.length === 0 ? (
          <Typography sx={{ fontSize: 11, color: '#bbb', textAlign: 'center', py: 2 }}>Nothing pending — all clients scheduled 🎉</Typography>
        ) : list.map((client) => {
          const ip = client.type === 'In-person';
          const pClr = PRIORITY_COLOR[this.clientPriority(client)] || C.low;
          return (
            <Paper key={`u_${client.clientId}`} elevation={0}
              onClick={() => this.openScheduleForClient(client)}
              sx={{ display: 'flex', mb: 0.8, borderRadius: 1.5, border: '1px solid #e8e8e8', overflow: 'hidden', cursor: 'pointer', '&:active': { bgcolor: '#f7f7f7' } }}>
              <Box sx={{ width: 4, flexShrink: 0, bgcolor: pClr }} />
              <Box sx={{ p: 1, flex: 1, minWidth: 0 }}>
                <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 0.5 }}>
                  <Typography sx={{ fontSize: 12, fontWeight: 700, color: '#222', lineHeight: 1.3 }}>{client.clientName}</Typography>
                  {(client.offers && client.offers.length > 0) || (client.debtors && client.debtors.length > 0) ? (
                    <IconButton size="small" sx={{ p: '2px' }} onClick={(e) => { e.stopPropagation(); this.setState({ detailClient: this.offerFromClient(client) }); }} title="Client detail"><Business sx={{ fontSize: 15, color: C.brand }} /></IconButton>
                  ) : null}
                </Box>
                {(client.offers || []).slice(0, 1).map((o) => (
                  <Typography key={o.id} sx={{ fontSize: 10.5, color: '#888' }} noWrap>📄 {o.name}</Typography>
                ))}
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.8, mt: 0.5, flexWrap: 'wrap' }}>
                  <Chip size="small"
                    icon={ip ? <LocationOn sx={{ fontSize: '12px !important', color: `${C.sysBadgeText} !important` }} /> : <Phone sx={{ fontSize: '12px !important', color: '#1a5276 !important' }} />}
                    label={ip ? 'In-person' : 'Call'}
                    sx={{ height: 19, fontSize: 10, fontWeight: 600, bgcolor: ip ? C.inPersonBg : C.callBg, color: ip ? C.sysBadgeText : '#1a5276', border: `1px solid ${ip ? C.inPersonBorder : C.callBorder}`, '& .MuiChip-label': { px: 0.6 } }} />
                  {client.totalValue > 0 && <Typography sx={{ fontSize: 10.5, fontWeight: 700, color: C.brand }}>{client.totalValueFormatted}</Typography>}
                  {client.hasOverdueDebtors && <Chip label="overdue" size="small" sx={{ height: 18, fontSize: 9.5, fontWeight: 700, bgcolor: '#FEEDED', color: '#B71C1C', border: '1px solid #F5C6C6', '& .MuiChip-label': { px: 0.6 } }} />}
                  {client.sysRank && <Chip label={`Sys #${client.sysRank}`} size="small" sx={{ height: 18, fontSize: 9.5, fontWeight: 700, bgcolor: C.sysBadgeBg, color: C.sysBadgeText, border: `1px solid ${C.inPersonBorder}`, '& .MuiChip-label': { px: 0.6 } }} />}
                </Box>
              </Box>
            </Paper>
          );
        })}
      </Box>
    );
  }

  // ─── Render: schedule dialog ────────────────────────────────────────────────
  renderDropDialog() {
    const { dropDialogOpen, dropPendingOffer, dropPendingDay, dropPendingFromSlotId, dropTime, dropDuration, dropReminder, dropVisitType, dropConflict } = this.state;
    if (!dropDialogOpen) return null;
    const isIP   = dropVisitType === 'In-person';
    const isEdit = Boolean(dropPendingFromSlotId);
    return (
      <Dialog open={dropDialogOpen} onClose={this.cancelDrop} maxWidth="xs" fullWidth
        PaperProps={{ sx: { mx: { xs: 1, sm: 3 }, width: { xs: 'calc(100% - 16px)', sm: 'auto' } } }}>
        <DialogTitle sx={{ pb: 0.5 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            {isIP ? <LocationOn sx={{ color: C.sysBadgeText, fontSize: 20 }} /> : <Phone sx={{ color: '#1a5276', fontSize: 20 }} />}
            <Box>
              <Typography fontWeight={700} sx={{ fontSize: 14, lineHeight: 1.3 }}>{isEdit ? 'Edit Schedule' : 'Schedule Visit'}</Typography>
              {dropPendingOffer && <Typography variant="caption" color="text.secondary">{dropPendingOffer.name} · {dropPendingDay}</Typography>}
            </Box>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ pt: 1 }}>
          <Stack spacing={2.2} sx={{ mt: 1 }}>
            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><CalendarToday sx={{ fontSize: 14 }} /> Day</Typography>
              <FormControl fullWidth size="small">
                <Select value={dropPendingDay} onChange={(e) => this.setState({ dropPendingDay: e.target.value, dropConflict: '' })}>
                  {this.getWeekDates().map((d) => <MenuItem key={d.day} value={d.day}>{DAY_FULL[d.day].charAt(0) + DAY_FULL[d.day].slice(1).toLowerCase()}, {d.month} {d.date}</MenuItem>)}
                </Select>
              </FormControl>
            </Box>
            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.8 }}>Visit Type</Typography>
              <Box sx={{ display: 'flex', gap: 1 }}>
                <Box onClick={() => this.setState({ dropVisitType: 'In-person', dropConflict: '' })}
                  sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6, py: 1, borderRadius: 1.5, cursor: 'pointer', border: '1.5px solid', borderColor: isIP ? C.inPersonBorder : '#e0e0e0', bgcolor: isIP ? C.inPersonBg : 'white' }}>
                  <LocationOn sx={{ fontSize: 16, color: isIP ? C.sysBadgeText : '#bbb' }} />
                  <Typography sx={{ fontSize: 12, fontWeight: isIP ? 700 : 400, color: isIP ? C.sysBadgeText : '#aaa' }}>In-person</Typography>
                </Box>
                <Box onClick={() => this.setState({ dropVisitType: 'Call', dropConflict: '' })}
                  sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6, py: 1, borderRadius: 1.5, cursor: 'pointer', border: '1.5px solid', borderColor: !isIP ? C.callBorder : '#e0e0e0', bgcolor: !isIP ? C.callBg : 'white' }}>
                  <Phone sx={{ fontSize: 16, color: !isIP ? '#1a5276' : '#bbb' }} />
                  <Typography sx={{ fontSize: 12, fontWeight: !isIP ? 700 : 400, color: !isIP ? '#1a5276' : '#aaa' }}>Call</Typography>
                </Box>
              </Box>
            </Box>
            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><AccessTime sx={{ fontSize: 14 }} /> Start Time</Typography>
              <TextField type="time" value={dropTime} onChange={(e) => this.setState({ dropTime: e.target.value, dropConflict: '' })} fullWidth size="small" InputLabelProps={{ shrink: true }} error={Boolean(dropConflict)} />
              {dropConflict && (
                <Box sx={{ mt: 1, px: 1.5, py: 1, bgcolor: '#FFF3F3', border: '1px solid #F5C6C6', borderRadius: 1.5 }}>
                  <Typography sx={{ fontSize: 11, color: '#B71C1C', lineHeight: 1.5 }}>⚠️ {dropConflict}</Typography>
                </Box>
              )}
            </Box>
            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><CalendarToday sx={{ fontSize: 14 }} /> Duration</Typography>
              <FormControl fullWidth size="small">
                <Select value={dropDuration} onChange={(e) => this.setState({ dropDuration: e.target.value, dropConflict: '' })}>
                  {DURATION_OPTIONS.map((o) => <MenuItem key={o.value} value={o.value}>{o.label}</MenuItem>)}
                </Select>
              </FormControl>
            </Box>
            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><NotificationsNone sx={{ fontSize: 14 }} /> Reminder</Typography>
              <FormControl fullWidth size="small">
                <Select value={dropReminder} onChange={(e) => this.setState({ dropReminder: e.target.value })}>
                  {REMINDER_OPTIONS.map((o) => <MenuItem key={o.value} value={o.value}>{o.label}</MenuItem>)}
                </Select>
              </FormControl>
            </Box>
          </Stack>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2, gap: 1 }}>
          <Button onClick={this.cancelDrop} sx={{ textTransform: 'none', color: '#666' }}>Cancel</Button>
          <Button variant="contained" onClick={this.confirmDrop} sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, px: 3 }}>{isEdit ? 'Update' : 'Schedule'}</Button>
        </DialogActions>
      </Dialog>
    );
  }

  // ─── Render: Add Visit dialog (name, day, type, time, duration, reminder) ────
  renderAddDialog() {
    const { addOpen, addName, addDay, addType, addTime, addDuration, addReminder, addConflict, addSaving } = this.state;
    if (!addOpen) return null;
    const isIP  = addType === 'In-person';
    const dates = this.getWeekDates();
    return (
      <Dialog open={addOpen} onClose={this.cancelAdd} maxWidth="xs" fullWidth
        PaperProps={{ sx: { mx: { xs: 1, sm: 3 }, width: { xs: 'calc(100% - 16px)', sm: 'auto' } } }}>
        <DialogTitle sx={{ pb: 0.5 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <AddLocationAlt sx={{ color: C.brand, fontSize: 20 }} />
            <Typography fontWeight={700} sx={{ fontSize: 14 }}>Add Visit</Typography>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ pt: 1 }}>
          <Stack spacing={2.2} sx={{ mt: 1 }}>
            <TextField autoFocus label="Client name" fullWidth size="small" value={addName} onChange={(e) => this.setState({ addName: e.target.value })} />

            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><CalendarToday sx={{ fontSize: 14 }} /> Day</Typography>
              <FormControl fullWidth size="small">
                <Select value={addDay} onChange={(e) => this.setState({ addDay: e.target.value, addConflict: '' })}>
                  {dates.map((d) => <MenuItem key={d.day} value={d.day}>{DAY_FULL[d.day].charAt(0) + DAY_FULL[d.day].slice(1).toLowerCase()}, {d.month} {d.date}</MenuItem>)}
                </Select>
              </FormControl>
            </Box>

            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.8 }}>Visit Type</Typography>
              <Box sx={{ display: 'flex', gap: 1 }}>
                <Box onClick={() => this.setState({ addType: 'In-person', addConflict: '' })}
                  sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6, py: 1, borderRadius: 1.5, cursor: 'pointer', border: '1.5px solid', borderColor: isIP ? C.inPersonBorder : '#e0e0e0', bgcolor: isIP ? C.inPersonBg : 'white' }}>
                  <LocationOn sx={{ fontSize: 16, color: isIP ? C.sysBadgeText : '#bbb' }} /><Typography sx={{ fontSize: 12, fontWeight: isIP ? 700 : 400, color: isIP ? C.sysBadgeText : '#aaa' }}>In-person</Typography>
                </Box>
                <Box onClick={() => this.setState({ addType: 'Call', addConflict: '' })}
                  sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.6, py: 1, borderRadius: 1.5, cursor: 'pointer', border: '1.5px solid', borderColor: !isIP ? C.callBorder : '#e0e0e0', bgcolor: !isIP ? C.callBg : 'white' }}>
                  <Phone sx={{ fontSize: 16, color: !isIP ? '#1a5276' : '#bbb' }} /><Typography sx={{ fontSize: 12, fontWeight: !isIP ? 700 : 400, color: !isIP ? '#1a5276' : '#aaa' }}>Call</Typography>
                </Box>
              </Box>
            </Box>

            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><AccessTime sx={{ fontSize: 14 }} /> Start Time</Typography>
              <TextField type="time" value={addTime} onChange={(e) => this.setState({ addTime: e.target.value, addConflict: '' })} fullWidth size="small" InputLabelProps={{ shrink: true }} error={Boolean(addConflict)} />
              {addConflict && (
                <Box sx={{ mt: 1, px: 1.5, py: 1, bgcolor: '#FFF3F3', border: '1px solid #F5C6C6', borderRadius: 1.5 }}>
                  <Typography sx={{ fontSize: 11, color: '#B71C1C', lineHeight: 1.5 }}>⚠️ {addConflict}</Typography>
                </Box>
              )}
            </Box>

            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><CalendarToday sx={{ fontSize: 14 }} /> Duration</Typography>
              <FormControl fullWidth size="small">
                <Select value={addDuration} onChange={(e) => this.setState({ addDuration: e.target.value, addConflict: '' })}>
                  {DURATION_OPTIONS.map((o) => <MenuItem key={o.value} value={o.value}>{o.label}</MenuItem>)}
                </Select>
              </FormControl>
            </Box>

            <Box>
              <Typography sx={{ fontSize: 11, fontWeight: 600, color: '#555', mb: 0.5, display: 'flex', alignItems: 'center', gap: 0.5 }}><NotificationsNone sx={{ fontSize: 14 }} /> Reminder</Typography>
              <FormControl fullWidth size="small">
                <Select value={addReminder} onChange={(e) => this.setState({ addReminder: e.target.value })}>
                  {REMINDER_OPTIONS.map((o) => <MenuItem key={o.value} value={o.value}>{o.label}</MenuItem>)}
                </Select>
              </FormControl>
            </Box>
          </Stack>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2, gap: 1 }}>
          <Button onClick={this.cancelAdd} disabled={addSaving} sx={{ textTransform: 'none', color: '#666' }}>Cancel</Button>
          <Button variant="contained" onClick={this.confirmAdd} disabled={addSaving} sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, px: 3 }}>
            {addSaving ? <><CircularProgress size={15} color="inherit" />&nbsp;Saving…</> : 'Add & Save'}
          </Button>
        </DialogActions>
      </Dialog>
    );
  }

  // ─── Render: Add Client dialog (ported from CheckIn → tbl_temp_client_details) ─
  renderAddClientDialog() {
    const { acOpen, acName, acPhone, acContactPerson, acCity, acState, acRegion, acRegionsData, acRegionsLoading, acSaving } = this.state;
    if (!acOpen) return null;
    return (
      <Dialog open={acOpen} onClose={this.cancelAddClient} maxWidth="xs" fullWidth
        PaperProps={{ sx: { mx: { xs: 1, sm: 3 }, width: { xs: 'calc(100% - 16px)', sm: 'auto' } } }}>
        <DialogTitle sx={{ pb: 0.5 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <PersonAdd sx={{ color: C.brand, fontSize: 20 }} />
            <Typography fontWeight={700} sx={{ fontSize: 14 }}>Add Client</Typography>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ pt: 1 }}>
          <Stack spacing={2} sx={{ mt: 1 }}>
            <TextField label="Client Name" fullWidth size="small" value={acName} onChange={(e) => this.setState({ acName: e.target.value })} />
            <TextField label="Phone Number" fullWidth size="small" value={acPhone} inputProps={{ inputMode: 'numeric', maxLength: 10 }}
              onChange={(e) => this.setState({ acPhone: e.target.value.replace(/\D/g, '').slice(0, 10) })} />
            <TextField label="Contact Person Name" fullWidth size="small" value={acContactPerson} onChange={(e) => this.setState({ acContactPerson: e.target.value })} />
            <TextField label="City" fullWidth size="small" value={acCity} onChange={(e) => this.setState({ acCity: e.target.value })} />
            <TextField label="State" fullWidth size="small" value={acState} onChange={(e) => this.setState({ acState: e.target.value })} />
            <TextField select label="Region" fullWidth size="small" value={acRegion} disabled={acRegionsLoading}
              helperText={acRegionsLoading ? 'Loading regions…' : ''}
              onChange={(e) => this.setState({ acRegion: e.target.value })}>
              {acRegionsData.map((region, idx) => <MenuItem key={idx} value={region}>{region}</MenuItem>)}
            </TextField>
          </Stack>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2, gap: 1 }}>
          <Button onClick={this.cancelAddClient} disabled={acSaving} sx={{ textTransform: 'none', color: '#666' }}>Cancel</Button>
          <Button variant="contained" onClick={this.saveNewClient} disabled={acSaving} sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, px: 3 }}>
            {acSaving ? <><CircularProgress size={15} color="inherit" />&nbsp;Saving…</> : 'Save'}
          </Button>
        </DialogActions>
      </Dialog>
    );
  }

  // ─── Render: client detail sheet ────────────────────────────────────────────
  renderClientDetail() {
    const { detailClient } = this.state;
    if (!detailClient) return null;
    const STATUS_COLOR = {
      Prospect:  { bg: '#EAF3DE', color: '#27500A' },
      Pending:   { bg: '#FFF8EE', color: '#BA7517' },
      Budgetary: { bg: '#F5F5F5', color: '#555555' },
    };
    const offers  = detailClient.offers || [];
    const debtors = detailClient.debtors || [];
    return (
      <Dialog open={Boolean(detailClient)} onClose={() => this.setState({ detailClient: null })} maxWidth="xs" fullWidth
        PaperProps={{ sx: { mx: { xs: 1, sm: 3 }, width: { xs: 'calc(100% - 16px)', sm: 'auto' }, borderRadius: 2, overflow: 'hidden' } }}>
        <Box sx={{ px: 2, py: 1.5, bgcolor: C.brand, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 0 }}>
            <Business sx={{ color: 'white', fontSize: 20, flexShrink: 0 }} />
            <Box sx={{ minWidth: 0 }}>
              <Typography sx={{ fontSize: 13, fontWeight: 700, color: 'white', lineHeight: 1.3 }} noWrap>{detailClient.name}</Typography>
              <Typography sx={{ fontSize: 10.5, color: 'rgba(255,255,255,0.8)' }}>
                {offers.length} offer{offers.length !== 1 ? 's' : ''}{detailClient.totalValueFormatted ? ` · ${detailClient.totalValueFormatted}` : ''}
                {debtors.length > 0 && detailClient.totalDebtorAmountFormatted ? ` · ${detailClient.totalDebtorAmountFormatted} due` : ''}
              </Typography>
            </Box>
          </Box>
          <IconButton size="small" onClick={() => this.setState({ detailClient: null })} sx={{ color: 'white', p: '4px' }}><Close sx={{ fontSize: 16 }} /></IconButton>
        </Box>
        <Box sx={{ maxHeight: 380, overflowY: 'auto' }}>
          {offers.length === 0 && debtors.length === 0 && (
            <Typography sx={{ fontSize: 11, color: '#aaa', textAlign: 'center', py: 3 }}>No offer / debtor details.</Typography>
          )}
          {offers.map((offer, idx) => {
            const sc = STATUS_COLOR[offer.status] || STATUS_COLOR.Budgetary;
            return (
              <Box key={offer.id || idx}>
                <Box sx={{ px: 2, py: 1.2 }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.4 }}>
                    <Typography sx={{ fontSize: 10.5, fontWeight: 700, color: '#333' }} noWrap>{offer.offerNo}</Typography>
                    <Chip label={offer.status} size="small" sx={{ height: 17, fontSize: 9.5, fontWeight: 600, bgcolor: sc.bg, color: sc.color, '& .MuiChip-label': { px: 0.8 } }} />
                  </Box>
                  <Typography sx={{ fontSize: 11, color: '#444', lineHeight: 1.4 }}>{offer.name}</Typography>
                  <Box sx={{ display: 'flex', gap: 2, mt: 0.6, flexWrap: 'wrap' }}>
                    <Box>
                      <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Value</Typography>
                      <Typography sx={{ fontSize: 11, fontWeight: 700, color: C.brand }}>{offer.valueFormatted}</Typography>
                    </Box>
                    {offer.expectedDate && (
                      <Box>
                        <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Expected</Typography>
                        <Typography sx={{ fontSize: 11, color: '#444' }}>{new Date(offer.expectedDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</Typography>
                      </Box>
                    )}
                    {offer.reminderDate && (
                      <Box>
                        <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Reminder</Typography>
                        <Typography sx={{ fontSize: 11, color: offer.isOverdue ? C.high : '#444' }}>{new Date(offer.reminderDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}{offer.isOverdue ? ' · Overdue' : ''}</Typography>
                      </Box>
                    )}
                  </Box>
                </Box>
                {idx < offers.length - 1 && <Divider />}
              </Box>
            );
          })}
          {debtors.length > 0 && (
            <Box>
              <Box sx={{ px: 2, py: 1, bgcolor: '#FFF5F5', borderTop: '2px solid #e0e0e0', display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography sx={{ fontSize: 10, fontWeight: 700, color: '#B71C1C', textTransform: 'uppercase' }}>Debtors</Typography>
                {detailClient.totalDebtorAmountFormatted && <Chip label={detailClient.totalDebtorAmountFormatted} size="small" sx={{ height: 16, fontSize: 9.5, fontWeight: 700, bgcolor: '#FEEDED', color: '#B71C1C', border: '1px solid #F5C6C6', '& .MuiChip-label': { px: 0.8 } }} />}
              </Box>
              {debtors.map((d, idx) => (
                <Box key={d.invoiceno || idx}>
                  <Box sx={{ px: 2, py: 1.2, bgcolor: d.isOverdue ? '#FFFAFA' : 'white' }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.4 }}>
                      <Typography sx={{ fontSize: 10.5, fontWeight: 700, color: '#333' }}>{d.invoiceno}</Typography>
                      {d.isOverdue && <Chip label={`${d.overdue_days}d overdue`} size="small" sx={{ height: 17, fontSize: 9.5, fontWeight: 600, bgcolor: '#FEEDED', color: '#B71C1C', border: '1px solid #F5C6C6', '& .MuiChip-label': { px: 0.8 } }} />}
                    </Box>
                    {d.projectName ? <Typography sx={{ fontSize: 11, color: '#444' }}>{d.projectName}</Typography> : null}
                    <Box sx={{ display: 'flex', gap: 2, mt: 0.6 }}>
                      <Box>
                        <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Amount</Typography>
                        <Typography sx={{ fontSize: 11, fontWeight: 700, color: '#B71C1C' }}>{d.invoiceAmountFmt}</Typography>
                      </Box>
                      {d.paymentduedate && (
                        <Box>
                          <Typography sx={{ fontSize: 9, color: '#aaa', textTransform: 'uppercase' }}>Due</Typography>
                          <Typography sx={{ fontSize: 11, color: d.isOverdue ? '#B71C1C' : '#444' }}>{new Date(d.paymentduedate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</Typography>
                        </Box>
                      )}
                    </Box>
                  </Box>
                  {idx < debtors.length - 1 && <Divider />}
                </Box>
              ))}
            </Box>
          )}
        </Box>
      </Dialog>
    );
  }

  // ─── Render: bottom bar ─────────────────────────────────────────────────────
  renderBottomBar() {
    const { planSaving, planStatus, marking } = this.state;
    const { total, visits, calls, unscheduled } = this.getStats();
    return (
      <Paper elevation={3} sx={{ borderRadius: 0, flexShrink: 0, zIndex: 3, borderTop: '1px solid #e0e0e0' }}>
        <Box sx={{ px: 1.5, pt: 0.8, display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 0.5 }}>
          <Typography sx={{ fontSize: 11, color: '#555' }}>
            <b>{total}</b> scheduled · <b>{visits}</b> visits · <b>{calls}</b> calls · <b style={{ color: C.high }}>{unscheduled}</b> <span style={{ color: C.high }}>unscheduled</span>
          </Typography>
        </Box>
        <Box sx={{ px: 1.5, py: 1, display: 'flex', gap: 1 }}>
          <Button variant="outlined" size="small" startIcon={marking ? <CircularProgress size={14} color="inherit" /> : <HowToReg fontSize="small" />} onClick={this.markAttendance} disabled={marking}
            sx={{ textTransform: 'none', borderColor: '#bbb', color: '#444', fontSize: 12, minHeight: 40, flex: 1 }}>Attendance</Button>
          <Button variant="outlined" size="small" onClick={this.saveDraft} disabled={planSaving}
            sx={{ textTransform: 'none', borderColor: '#bbb', color: '#444', fontSize: 12, minHeight: 40, flex: 1 }}>{planSaving ? 'Saving…' : 'Save draft'}</Button>
          <Button variant="contained" size="small" onClick={this.submitToRM} disabled={planSaving || planStatus === 'Submitted' || planStatus === 'Approved'}
            sx={{ textTransform: 'none', bgcolor: C.brand, '&:hover': { bgcolor: '#3d35a0' }, fontSize: 12, minHeight: 40, flex: 1.4 }}>Submit to RM</Button>
        </Box>
      </Paper>
    );
  }

  render() {
    if (this.state.LogoutFlag) return <LoggedOut />;
    const { queueLoading, queueError } = this.state;
    return (
      <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh', bgcolor: '#f5f6f8', overflow: 'hidden', maxWidth: 640, mx: 'auto' }}>
        {this.renderTopBar()}
        {this.renderDayStrip()}
        <Box sx={{ flex: 1, overflowY: 'auto', px: 1.5, py: 1.2 }}>
          {queueLoading ? (
            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', mt: 5, gap: 1 }}>
              <CircularProgress size={26} sx={{ color: C.brand }} />
              <Typography sx={{ fontSize: 12, color: '#aaa' }}>Loading your plan…</Typography>
            </Box>
          ) : (
            <>
              {this.renderDaySections()}
              {queueError
                ? <Box sx={{ textAlign: 'center', mt: 2 }}>
                    <Typography sx={{ fontSize: 11, color: C.high, mb: 1 }}>{queueError}</Typography>
                    <Button size="small" onClick={this.loadClientQueue} sx={{ fontSize: 11, textTransform: 'none', color: C.brand }}>Retry</Button>
                  </Box>
                : this.renderUnscheduled()}
            </>
          )}
        </Box>
        {this.renderBottomBar()}
        {this.renderDropDialog()}
        {this.renderAddDialog()}
        {this.renderAddClientDialog()}
        {this.renderClientDetail()}
        <Snackbar open={this.state.SnackBar} autoHideDuration={this.state.SnackbarTimeOut}
          onClose={() => this.setState({ SnackBar: false })} anchorOrigin={{ vertical: 'top', horizontal: 'center' }}>
          <Alert onClose={() => this.setState({ SnackBar: false })} severity={this.state.SnackBarVariant} sx={{ width: '100%' }}>{this.state.snackBarMessage}</Alert>
        </Snackbar>
      </Box>
    );
  }
}

export default MyVisitPlan;
